import {validate as structure,animatable} from './model.js';
const color=v=>typeof v==='string'&&/^(#[0-9a-f]{3,8}|none|transparent)$/i.test(v);
function nodes(value){if(!Array.isArray(value)||value.length>20000)throw Error('Invalid path geometry.');for(const p of value){for(const pt of [p,p.in,p.out].filter(Boolean))if(!Number.isFinite(pt.x)||!Number.isFinite(pt.y))throw Error('Invalid path node.');}}
const validId=v=>typeof v==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(v);
export function validate(p){structure(p);if(!validId(p.id))throw Error('Invalid project ID.');if(typeof p.name!=='string'||!color(p.background))throw Error('Invalid project metadata.');const visit=list=>list.forEach(n=>{if(!validId(n.id))throw Error('Invalid object ID.');if(n.prefix&&(!Array.isArray(n.prefix)||n.prefix.length!==6||n.prefix.some(v=>!Number.isFinite(v))))throw Error('Invalid transform matrix.');if(!color(n.fill)||!color(n.stroke)||n.width<0||n.height<0)throw Error('Invalid artwork styling.');nodes(n.nodes||[]);if(n.mesh){const m=n.mesh;if(!Number.isInteger(m.rows)||!Number.isInteger(m.cols)||m.rows<2||m.cols<2||m.rows>7||m.cols>7||!Array.isArray(m.points)||m.points.length!==m.rows*m.cols||!m.bounds||!['x','y','width','height'].every(k=>Number.isFinite(m.bounds[k]))||m.bounds.width<=0||m.bounds.height<=0||m.points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)||!/^#[0-9a-f]{6}$/i.test(p.color)))throw Error('Invalid colour mesh.');}if(n.radius!==undefined&&(!Number.isFinite(n.radius)||n.radius<0))throw Error('Invalid corner radius.');if(n.rawPath&&(typeof n.rawPath!=='string'||n.rawPath.length>1000000))throw Error('Invalid SVG path.');if(typeof n.text!=='string'||typeof n.font!=='string'||!Number.isFinite(n.fontSize)||n.fontSize<=0)throw Error('Invalid text.');for(const [prop,track] of Object.entries(n.tracks||{})){const times=new Set();for(const k of track){if(!validId(k.id)||times.has(k.time)||!['hold','linear','easeIn','easeOut','easeInOut'].includes(k.easing))throw Error('Invalid or duplicate keyframe.');times.add(k.time);if(prop==='nodes')nodes(k.value);else if(['fill','stroke'].includes(prop)){if(!color(k.value))throw Error('Invalid keyframe colour.');}else if(!Number.isFinite(k.value))throw Error('Invalid numeric keyframe.');}}visit(n.children||[]);});visit(p.layers);if(p.audio){const a=p.audio;for(const key of ['offset','trimStart','trimEnd','volume','duration'])if(!Number.isFinite(a[key]))throw Error('Invalid audio placement.');if(a.offset<0||a.trimStart<0||a.trimEnd<a.trimStart||a.trimEnd>a.duration||a.volume<0||a.volume>2)throw Error('Invalid audio trim.');if(!validId(a.assetId))throw Error('Missing audio asset.');}return p;}
